/* Retail calls sprintf without a prototype (no crclr before the call, mess fn_1_EA84 / EC1C):
 * keep stdio.h out of the CodeWarrior build, give the host its real declaration. */
#ifndef __MWERKS__
#include <stdio.h>
#endif

/* Message ids of this mode (MESS_MG_WARS directory, no messnum header exists for it) */
#define MGWARS_MES(no) MESSNUM(MESS_MG_WARS, (no))

/*
 * Structures. Offsets in the comments are the GameCube ones (the reference objects); they hold
 * only under __MWERKS__. On the 64-bit host every pointer slot below is 8 bytes, so the host
 * layout differs: never address a field with a GC offset or stride, and never memset/memcpy a
 * struct with a GC size.
 */

/* mgwars.c lbl_1_data_0: the 26 candidate minigames; fn_1_728C fills mgIdx (the mgDataTbl
 * index whose .ovl == ovl) and copies the unlocked ones (GWMgUnlockGet(mgIdx + 501)) into
 * MGWARS_WORK.mg[] with a 6-byte struct copy (three lhz/sth). */
typedef struct MgWarsMg_s {
    u16 ovl; /* 0x0 DLL number, compared with mgDataTbl[].ovl (cmplw) */
    s16 mgNo; /* 0x2 5xx minigame number (lha; GWMgUnlockSet) */
    s8 mgIdx; /* 0x4 mgDataTbl index (stb / lbz+extsb) */
    s8 battleF; /* 0x5 mgDataTbl[mgIdx].type == MG_TYPE_BATTLE (fn_1_728C) */
} MGWARS_MG; /* 0x6 */

/* mgwars.c lbl_1_data_2D8: the 19 board panels (hexagonal grid). Written at run time. */
typedef struct MgWarsPanel_s {
    s8 link[6]; /* 0x0 neighbour panel per direction, -1 = none */
    s8 owner; /* 0x6 player owning the panel, -1 = free (fn_1_34FC, fn_1_2F28) */
    s8 unk7; /* 0x7 fn_1_3458 stores its second argument */
    s8 unk8; /* 0x8 flag, set to 1 (fn_1_34FC, fn_1_3554) */
    s8 unk9; /* 0x9 flag, set to 1 (fn_1_3554, fn_1_3D38, fn_1_4170) */
} MGWARS_PANEL; /* 0xA */

/* MGWARS_WORK.player[] (0x1C); decathlon's DECAWORK_PLAYER with four motions */
typedef struct MgWarsPlayer_s {
    HU3DMODELID mdlId; /* 0x00 CharModelMotListCreate result */
    HU3DMOTID motId[4]; /* 0x02 CharModelMotListCreate(charNo, 2, lbl_1_data_9C, motId) */
    s16 no; /* 0x0A player number */
    s16 charNo; /* 0x0C GwPlayerConf[no].charNo */
    s16 padNo; /* 0x0E GwPlayerConf[no].padNo */
    s8 mot; /* 0x10 current motion slot, -1 at init */
    float rot; /* 0x14 current Y rotation (fn_1_6444: *angle of the angle step fn_1_21C) */
    float rotEnd; /* 0x18 target Y rotation (fn_1_6444) */
} MGWARS_PLAYER; /* 0x1C */

/* mgwars.c lbl_1_bss_8 (lbl_1_bss_0 points to it, set in fn_1_728C) */
typedef struct MgWarsWork_s {
    OMOBJMAN *objman; /* 0x000 omInitObjMan(200, 1000). HOST: pointer */
    s16 cameraMot; /* 0x004 mdlId[] index of the running camera motion, -1 = none (fn_1_C04) */
    HUWINID winId; /* 0x006 HuWinExCreate (fn_1_50C) */
    s8 unk8; /* 0x008 player number, read by fn_1_5C4 */
    s16 unkA; /* 0x00A read by fn_1_5D8 (mess fn_1_EA84 prints it with "%d") */
    u32 mesFlag; /* 0x00C fn_1_6F4 set / fn_1_728 reset / fn_1_7A0 get */
    u32 flag; /* 0x010 fn_1_64C set / fn_1_668 reset / fn_1_684 get; 0x10000 = message window busy (fn_1_728 waits, fn_1_6F4 clears), 0x40 = window open */
    s8 unk14[4]; /* 0x014 player numbers, copied out by fn_1_5EC; fn_1_4EE8 camera order */
    s8 unk18; /* 0x018 entries used in unk14 (fn_1_5EC return) */
    s8 unk19; /* 0x019 read by fn_1_638 (mess fn_1_EC1C prints it with "%2d") */
    MGWARS_MG mg[26]; /* 0x01A unlocked entries of lbl_1_data_0 */
    ANIMDATA *mgIcon[26]; /* 0x0B8 HuSprAnimRead(HuDataSelHeapReadNum(mgDataTbl[mg[i].mgIdx].instPic[0])) (fn_1_796C). HOST: pointers */
    s32 mgNum; /* 0x120 entries used in mg[] */
    s32 animId; /* 0x124 Hu3DAnimCreate result (extsh, stw), -1 = none */
    MGWARS_PLAYER player[4]; /* 0x128 */
    HU3DMODELID guideMdlId; /* 0x198 DATANUM(mgwars, 0) model, motion DATANUM(mgwars, 1) */
    s16 guidePosNo; /* 0x19A lbl_1_data_E0 index the guide walks to (fn_1_57C0) */
    HuVecF guideStart; /* 0x19C copy of guidePos when a walk starts (fn_1_57C0) */
    HuVecF guidePos; /* 0x1A8 Hu3DModelPosSet(guideMdlId) */
    float guideRotY; /* 0x1B4 */
    s32 guideTime; /* 0x1B8 fn_1_57C0: time - midTime */
    HuVecF guideMid; /* 0x1BC fn_1_57C0: intermediate point (lbl_1_data_E0[5..7]) */
    HuVecF guideEnd; /* 0x1C8 fn_1_57C0: lbl_1_data_E0[posNo] */
    s32 guideMidTime; /* 0x1D4 fn_1_57C0 */
    HU3DMODELID mdlId[75]; /* 0x1D8 stage models; [6 + panel] panel models; [66..74] camera models */
    HU3DMODELID panelMdlId[19][5]; /* 0x26E per panel, per owner state (fn_1_B34 / fn_1_4534 swap into mdlId[6 + panel]) */
    s16 unk32C[19]; /* 0x32C per panel: fn_1_4534 flip-animation phase 0..4 (0 start, 1 motion 121-150, 2 swap model at end, 3 motion 151-180, 4 idle loop) */
    HU3DMODELID unk352; /* 0x352 model id (Hu3DModelPosSet / AttrSet) */
    s32 unk354; /* 0x354 fn_1_8D9C argument */
    s16 playerRotMode; /* 0x358 fn_1_6FA8 argument (decathlon DecaPlayerRotateStart) */
    float playerRotSpeed; /* 0x35C fn_1_6FA8 argument */
    s16 cameraMotNext; /* 0x360 fn_1_83C argument 1, -1 = none (fn_1_498) */
    float cameraMotTime; /* 0x364 fn_1_83C argument 2 (fn_1_498 passes it to fn_1_C04 as int) */
    s16 cameraMotArg; /* 0x368 fn_1_83C argument 3 (fn_1_C04 argument 3) */
    s16 unk36A; /* 0x36A fn_1_7138 argument */
    s16 unk36C; /* 0x36C */
    BOOL dirRead; /* 0x370 fn_1_328 / fn_1_404 */
    int mgNoDir; /* 0x374 mgDataTbl index whose dataDir fn_1_328 reads (fn_1_404 argument) */
    int streamNo; /* 0x378 HuAudBGMPlay result, -1 = none */
    int seNo37C; /* 0x37C HuAudFXPlay result (fn_1_C620) */
    int seNo380; /* 0x380 HuAudFXPlay result (fn_1_C620) */
    int seNo; /* 0x384 HuAudFXPlay result of fn_1_189C, -1 = none */
    int seTime; /* 0x388 frames until fn_1_182C stops seNo */
    HUPROCESS *seProc; /* 0x38C fn_1_182C process (fn_1_189C). HOST: pointer */
    ANIMDATA *fbCopyAnim; /* 0x390 HuSprAnimMake; fn_1_11E8 layer hook. HOST: pointer */
    float fbCopyX; /* 0x394 fn_1_11E8 */
    float fbCopyY; /* 0x398 */
    float fbCopyW; /* 0x39C */
    float fbCopyH; /* 0x3A0 */
    HuVecF unk3A4; /* 0x3A4 struct-copied; x/y/z passed to Hu3DModelPosSet */
    HuVecF camTarget[4]; /* 0x3B0 fn_1_12AC / fn_1_4EE8: Hu3DCameraPosSet target, per camera slot */
    HuVecF camPos[4]; /* 0x3E0 fn_1_12AC / fn_1_4EE8: Hu3DCameraPosSet position, per camera slot */
} MGWARS_WORK; /* 0x410 */

/* The record lbl_1_bss_4 points to: it is the DOL's mgModeWork (fn_1_728C: lbl_1_bss_4 =
 * mgModeWork), so it survives the minigame call and the return to Mini-Game Wars. */
typedef struct MgWarsModeWork_s {
    s16 unk0; /* 0x00 counter: 0 at the start (fn_1_7E30), incremented / wrapped at 10 (fn_1_B614, fn_1_C19C) */
    s8 round; /* 0x02 index into mgOrder[]; = mgNum at the start, compared with mgNum (fn_1_796C) */
    u8 flag; /* 0x03 fn_1_69C set / fn_1_6BC reset / fn_1_6DC get */
    s8 mgOrder[26]; /* 0x04 indices into MGWARS_WORK.mg[], shuffled by fn_1_796C */
    s8 panelOwner[19]; /* 0x1E per panel: player number, -1 = free */
} MGWARS_MODEWORK; /* 0x31 */

/* score.c lbl_1_bss_418 */
typedef struct MgWarsScorePlayer_s {
    s32 score; /* 0x0 fn_1_F808 ++ / fn_1_F828 -- / fn_1_F848 = */
    HUSPRGRPID grpId; /* 0x4 HuSprGrpPosSet */
    MGSCORE *mgScore; /* 0x8 MgScorePosSet / MgScoreValueSet. HOST: pointer */
} MGWARS_SCOREPLAYER; /* 0xC */

typedef struct MgWarsScore_s {
    s16 mode; /* 0x00 fn_1_F860 / fn_1_F884 clear it; fn_1_F0B8 */
    s8 unk2; /* 0x02 fn_1_F0B8 (lbz+extsb, compared with 1) */
    s8 unk3; /* 0x03 fn_1_F860 = 0, fn_1_F884 = 1 (lbz+extsb in fn_1_F0B8) */
    MGWARS_SCOREPLAYER player[4]; /* 0x04 */
} MGWARS_SCORE; /* 0x34 */

/* score.c lbl_1_data_670 (one reference object) */
typedef struct MgWarsScoreLayout_s {
    HuVec2f pos[4][2];
    u32 dataNum[15];
} MGWARS_SCORELAYOUT;

